INSERT INTO DICH_VU (TenDV, MoTa, ThoiLuong, GiaDV, TrangThai) VALUES
('Khám tổng quát và tư vấn nha khoa', 'Kiểm tra tổng thể sức khỏe răng miệng, tầm soát sớm sâu răng, viêm nướu, cao răng và tư vấn kế hoạch chăm sóc răng miệng định kỳ chuẩn y khoa.', 30, 100000, 'DANG_AP_DUNG'),
('Lấy cao răng và đánh bóng siêu âm', 'Làm sạch mảng bám vôi răng trên và dưới nướu bằng công nghệ sóng siêu âm êm ái, hạn chế ê buốt, kết hợp đánh bóng men răng sáng sạch tự nhiên.', 45, 250000, 'DANG_AP_DUNG'),
('Trám răng thẩm mỹ Composite', 'Phục hồi răng sâu ngà, răng mẻ hoặc mòn cổ chân răng bằng chất liệu Composite cao cấp đồng màu răng tự nhiên, chiếu đèn quang trùng hợp bền chắc.', 45, 350000, 'DANG_AP_DUNG'),
('Điều trị tủy răng (Nội nha)', 'Làm sạch ống tủy viêm nhiễm, khử khuẩn triệt để và trám bít kín hệ thống ống tủy, bảo tồn răng thật tối đa. Được quản lý theo dõi theo đợt điều trị chuyên sâu.', 60, 850000, 'DANG_AP_DUNG'),
('Nhổ răng an toàn không đau', 'Nhổ răng sữa lung lay, răng sâu vỡ lớn hoặc chân răng còn sót theo chỉ định bác sĩ. Ứng dụng kỹ thuật gây tê vi điểm nhẹ nhàng, an toàn và mau lành thương.', 45, 500000, 'DANG_AP_DUNG'),
('Tiểu phẫu nhổ răng khôn (Răng số 8)', 'Tiểu phẫu loại bỏ răng khôn mọc lệch, mọc ngầm, đâm ngang gây đau buốt hoặc chèn ép răng bên cạnh, thực hiện vô trùng tuyệt đối với máy cắt siêu âm.', 60, 1500000, 'DANG_AP_DUNG'),
('Tẩy trắng răng công nghệ ánh sáng lạnh', 'Dịch vụ thẩm mỹ nha khoa làm sáng màu men răng 2-3 tông chỉ sau 60 phút, sử dụng thuốc tẩy trắng chính hãng kích hoạt bằng ánh sáng LED an toàn.', 60, 1200000, 'DANG_AP_DUNG'),
('Bọc răng sứ thẩm mỹ cao cấp', 'Phục hình răng sứ toàn phần tái tạo nụ cười hoàn hảo, cải thiện hình thể răng thưa, ố màu, vỡ lớn hoặc sau chữa tủy, bảo hành chính hãng lâu dài.', 60, 2500000, 'DANG_AP_DUNG'),
('Chụp X-quang nha khoa chẩn đoán hình ảnh', 'Chụp phim kiểm tra chẩn đoán tình trạng chân răng, xương ổ răng và cuống răng phục vụ nhổ răng, chữa tủy hoặc lập đợt điều trị (Dịch vụ phát sinh).', 15, 150000, 'DANG_AP_DUNG'),
('Tư vấn và lập phác đồ chỉnh nha (Niềng răng)', 'Khám chuyên sâu sai lệch khớp cắn, lấy mẫu dấu hàm, phân tích cấu trúc xương hàm và thiết lập phác đồ đợt điều trị chỉnh nha theo dõi tiến triển từng giai đoạn.', 45, 300000, 'DANG_AP_DUNG');
